    14  /// A payment in the payment core.
    15  ///
    16  /// A [`Payment`] holds the original amount and currency, its current lifecycle
    17  /// [`PaymentStatus`], how much of the amount has been captured and refunded so
    18  /// far, and an append-only journal of [`PaymentEvent`]s.
    19  ///
    20  /// # Lifecycle
    21  ///
    22  /// - `Created` → `Authorized` via [`authorize`](Payment::authorize)
    23  /// - `Authorized` → `PartiallyCaptured`/`Captured` via [`capture`](Payment::capture)
    24  /// - `Captured`/`PartiallyCaptured` → `PartiallyRefunded`/`Refunded` via
    25  ///   [`refund`](Payment::refund)
    26  /// - `Authorized` → `Voided` via [`void`](Payment::void)
    27  ///
    28  /// Capture and refund support partial amounts; the resulting status reflects
    29  /// whether the full amount was consumed.
    30  #[derive(Debug, Clone, PartialEq)]
    31  pub struct Payment {
    32      id: String,
    33      amount: Amount,
    34      currency: Currency,
    35      status: PaymentStatus,
    36      captured_amount: Amount,
    37      refunded_amount: Amount,
    38      events: Vec<PaymentEvent>,
    39  }
