     3  use std::fmt;
     4
     5  /// The lifecycle status of a [`crate::Payment`].
     6  ///
     7  /// Transitions follow a well-defined state machine:
     8  ///
     9  /// - `Created` → `Authorized` via [`authorize`](crate::Payment::authorize)
    10  /// - `Authorized` → `PartiallyCaptured`/`Captured` via
    11  ///   [`capture`](crate::Payment::capture)
    12  /// - `Captured`/`PartiallyCaptured` → `PartiallyRefunded`/`Refunded` via
    13  ///   [`refund`](crate::Payment::refund)
    14  /// - `Authorized` → `Voided` via [`void`](crate::Payment::void)
    15  #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
    16  pub enum PaymentStatus {
    17      /// The payment has been created but not yet authorized.
    18      Created,
    19      /// Funds have been authorized but not yet captured.
    20      Authorized,
    21      /// A portion of the authorized amount has been captured.
    22      PartiallyCaptured,
    23      /// The full authorized amount has been captured.
    24      Captured,
    25      /// A portion of the captured amount has been refunded.
    26      PartiallyRefunded,
    27      /// The full captured amount has been refunded.
    28      Refunded,
    29      /// The authorization was voided; no funds were captured.
    30      Voided,
    31  }
    32
    33  impl PaymentStatus {
    34      /// Returns `true` if no further transitions are possible from this status.
    35      pub fn is_terminal(self) -> bool {
    36          matches!(self, Self::Refunded | Self::Voided)
    37      }
    38  }
