    44              Self::Authorized => "authorized",
    45              Self::PartiallyCaptured => "partially_captured",
    46              Self::Captured => "captured",
    47              Self::PartiallyRefunded => "partially_refunded",
    48              Self::Refunded => "refunded",
    49              Self::Voided => "voided",
    50          };
    51          f.write_str(name)
    52      }
    53  }
