     1  //! # payment_core
     2  //!
     3  //! A small payment core library implementing a payment lifecycle state machine.
     4  //!
     5  //! The central type is [`Payment`], which holds an amount, a currency, and a
     6  //! lifecycle status. Operations such as [`authorize`](Payment::authorize),
     7  //! [`capture`](Payment::capture), [`refund`](Payment::refund) and
     8  //! [`void`](Payment::void) move the payment through well-defined status
     9  //! transitions and append an entry to an immutable, time-stamped event journal
    10  //! ([`PaymentEvent`]).
    11  //!
    12  //! # Example
    13  //!
    14  //! ```
    15  //! use payment_core::{Currency, Payment, PaymentStatus};
    16  //!
    17  //! let mut payment = Payment::new("inv_1", 2_500, Currency::EUR)?;
    18  //!
    19  //! payment.authorize()?;
    20  //! assert_eq!(payment.status(), PaymentStatus::Authorized);
    21  //!
    22  //! payment.capture(2_500)?;
    23  //! payment.refund(2_500)?;
    24  //! assert_eq!(payment.status(), PaymentStatus::Refunded);
    25  //!
    26  //! assert_eq!(payment.events().len(), 4);
    27  //! # Ok::<(), payment_core::PaymentError>(())
    28  //! ```
    29  //!
    30  //! Amounts are always expressed in the smallest currency unit (minor units),
    31  //! e.g. cents for `USD` or kopecks for `RUB`, and stored as unsigned integers
    32  //! to avoid floating point rounding errors.
    33
