    10  /// Errors that can occur while working with [`crate::Payment`].
    11  #[derive(Debug, Clone, PartialEq, Eq)]
    12  pub enum PaymentError {
    13      /// An operation was attempted that is not legal in the payment's current
    14      /// [`PaymentStatus`].
    15      InvalidTransition {
    16          /// The operation that was attempted, e.g. `"capture"`.
    17          operation: &'static str,
    18          /// The status the payment was in when the operation was attempted.
    19          current: PaymentStatus,
    20      },
    21      /// An amount of zero was supplied where a strictly positive amount is
    22      /// required.
    23      ZeroAmount,
    24      /// A capture amount exceeds the amount still authorized for capture.
    25      AmountExceedsAuthorized {
    26          /// The amount that was requested.
    27          amount: u64,
    28          /// The amount still available to capture.
    29          remaining: u64,
    30      },
    31      /// A refund amount exceeds the amount captured and not yet refunded.
    32      AmountExceedsCaptured {
    33          /// The amount that was requested.
    34          amount: u64,
    35          /// The amount still available to refund.
    36          available: u64,
    37      },
    38      /// A currency code could not be resolved to a known ISO-4217 code.
    39      UnknownCurrency(String),
    40      /// A payment id was empty or consisted only of whitespace.
    41      InvalidPaymentId,
    42  }
    43
    44  impl PaymentError {
    45      pub(crate) fn invalid_transition(operation: &'static str, current: PaymentStatus) -> Self {
    46          Self::InvalidTransition { operation, current }
    47      }
    48  }
    49
    50  impl fmt::Display for PaymentError {
    51      fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    52          match self {
    53              Self::InvalidTransition { operation, current } => {
    54                  write!(
    55                      f,
    56                      "operation '{operation}' is not allowed from status '{current}'"
    57                  )
    58              }
    59              Self::ZeroAmount => write!(f, "amount must be greater than zero"),
    60              Self::AmountExceedsAuthorized { amount, remaining } => {
    61                  write!(
    62                      f,
    63                      "capture amount {amount} exceeds remaining authorized amount {remaining}"
    64                  )
    65              }
    66              Self::AmountExceedsCaptured { amount, available } => {
    67                  write!(
    68                      f,
    69                      "refund amount {amount} exceeds captured amount available for refund {available}"
    70                  )
    71              }
    72              Self::UnknownCurrency(code) => write!(f, "unknown ISO-4217 currency code '{code}'"),
    73              Self::InvalidPaymentId => write!(f, "payment id must not be empty"),
    74          }
    75      }
    76  }
