     1  //! ISO-4217 currency support.
     2
     3  /// Defines a currency enum together with its three-letter ISO-4217 code
     4  /// mapping, `Display` (uppercase code), and case-insensitive `FromStr`.
     5  macro_rules! define_currency {
     6      (
     7          $(#[$meta:meta])*
     8          $name:ident {
     9              $($variant:ident => $code:literal),+ $(,)?
    10          }
    11      ) => {
    12          $(#[$meta])*
    13          #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
    14          pub enum $name {
    15              $($variant),+
    16          }
    17
    18          impl $name {
    19              /// Returns the three-letter ISO-4217 code of this currency, e.g. `"USD"`.
    20              pub fn code(self) -> &'static str {
    21                  match self {
    22                      $( $name::$variant => $code ),+
    23                  }
    24              }
    25          }
    26
    27          impl std::fmt::Display for $name {
    28              fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    29                  f.write_str(self.code())
    30              }
    31          }
    32
    33          impl std::str::FromStr for $name {
    34              type Err = crate::error::PaymentError;
    35
    36              fn from_str(s: &str) -> Result<Self, Self::Err> {
    37                  match s.trim().to_ascii_uppercase().as_str() {
    38                      $( $code => Ok($name::$variant), )+
    39                      other => Err(crate::error::PaymentError::UnknownCurrency(other.to_owned())),
    40                  }
    41              }
    42          }
    43
    44          impl TryFrom<&str> for $name {
    45              type Error = crate::error::PaymentError;
    46
    47              fn try_from(value: &str) -> Result<Self, Self::Error> {
    48                  value.parse()
    49              }
    50          }
    51
    52          impl TryFrom<String> for $name {
    53              type Error = crate::error::PaymentError;
    54
    55              fn try_from(value: String) -> Result<Self, Self::Error> {
    56                  value.as_str().parse()
    57              }
    58          }
    59      };
    60  }
