     1  //! The [`Payment`] entity and its lifecycle operations.
     2
     3  use crate::currency::Currency;
     4  use crate::error::{PaymentError, PaymentResult};
     5  use crate::event::{PaymentEvent, PaymentEventType};
     6  use crate::status::PaymentStatus;
     7
     8  /// An amount of money expressed in the smallest currency unit (minor units),
     9  /// e.g. cents for `USD` or kopecks for `RUB`.
    10  ///
    11  /// Stored as an unsigned integer to avoid floating point rounding errors.
    12  pub type Amount = u64;
    13
    14  /// A payment in the payment core.
    15  ///
    16  /// A [`Payment`] holds the original amount and currency, its current lifecycle
    17  /// [`PaymentStatus`], how much of the amount has been captured and refunded so
    18  /// far, and an append-only journal of [`PaymentEvent`]s.
    19  ///
    20  /// # Lifecycle
    21  ///
    22  /// - `Created` → `Authorized` via [`authorize`](Payment::authorize)
    23  /// - `Authorized` → `PartiallyCaptured`/`Captured` via [`capture`](Payment::capture)
    24  /// - `Captured`/`PartiallyCaptured` → `PartiallyRefunded`/`Refunded` via
    25  ///   [`refund`](Payment::refund)
    26  /// - `Authorized` → `Voided` via [`void`](Payment::void)
    27  ///
    28  /// Capture and refund support partial amounts; the resulting status reflects
    29  /// whether the full amount was consumed.
    30  #[derive(Debug, Clone, PartialEq)]
    31  pub struct Payment {
    32      id: String,
    33      amount: Amount,
    34      currency: Currency,
    35      status: PaymentStatus,
    36      captured_amount: Amount,
    37      refunded_amount: Amount,
    38      events: Vec<PaymentEvent>,
    39  }
    40
    41  impl Payment {
    42      /// Creates a new payment in the `Created` status.
    43      ///
    44      /// # Errors
    45      ///
    46      /// Returns [`PaymentError::InvalidPaymentId`] if `id` is empty or
    47      /// whitespace, and [`PaymentError::ZeroAmount`] if `amount` is zero.
    48      pub fn new(id: impl Into<String>, amount: Amount, currency: Currency) -> PaymentResult<Self> {
    49          let id = id.into();
    50          if id.trim().is_empty() {
    51              return Err(PaymentError::InvalidPaymentId);
    52          }
    53          if amount == 0 {
    54              return Err(PaymentError::ZeroAmount);
    55          }
    56
    57          let event = PaymentEvent::new(
    58              PaymentEventType::Created,
    59              None,
    60              PaymentStatus::Created,
    61              format!("payment '{id}' created for {amount} {currency}"),
    62          );
    63
    64          Ok(Self {
    65              id,
    66              amount,
    67              currency,
    68              status: PaymentStatus::Created,
    69              captured_amount: 0,
    70              refunded_amount: 0,
    71              events: vec![event],
    72          })
    73      }
    74
    75      /// Authorizes the payment, transitioning `Created` → `Authorized`.
    76      ///
    77      /// # Errors
    78      ///
    79      /// Returns [`PaymentError::InvalidTransition`] unless the payment is in the
    80      /// `Created` status.
    81      pub fn authorize(&mut self) -> PaymentResult<&PaymentEvent> {
    82          if self.status != PaymentStatus::Created {
    83              return Err(PaymentError::invalid_transition("authorize", self.status));
    84          }
    85
    86          self.status = PaymentStatus::Authorized;
    87          let description = format!("payment '{}' authorized", self.id);
    88          Ok(self.record(PaymentEventType::Authorized, None, description))
    89      }
    90
    91      /// Captures `amount` from the authorized amount.
    92      ///
    93      /// A capture may cover the full authorized amount (transitioning to
    94      /// `Captured`) or a portion of it (transitioning to `PartiallyCaptured`).
    95      ///
    96      /// # Errors
    97      ///
    98      /// - [`PaymentError::InvalidTransition`] if the payment is not
    99      ///   `Authorized` or `PartiallyCaptured`.
   100      /// - [`PaymentError::ZeroAmount`] if `amount` is zero.
   101      /// - [`PaymentError::AmountExceedsAuthorized`] if `amount` exceeds the
   102      ///   amount still available to capture.
   103      pub fn capture(&mut self, amount: Amount) -> PaymentResult<&PaymentEvent> {
   104          let current = self.status;
   105          if !matches!(
   106              current,
   107              PaymentStatus::Authorized | PaymentStatus::PartiallyCaptured
   108          ) {
   109              return Err(PaymentError::invalid_transition("capture", current));
   110          }
   111          if amount == 0 {
   112              return Err(PaymentError::ZeroAmount);
   113          }
   114
   115          let remaining = self.amount - self.captured_amount;
   116          if amount > remaining {
   117              return Err(PaymentError::AmountExceedsAuthorized { amount, remaining });
   118          }
   119
   120          self.captured_amount += amount;
   121          self.status = if self.captured_amount == self.amount {
   122              PaymentStatus::Captured
   123          } else {
   124              PaymentStatus::PartiallyCaptured
   125          };
