   107  /// `Payment` is a value type: every state-changing method consumes `self` and
   108  /// returns a new `Payment` (or an error), so an invalid transition can never
   109  /// leave a half-mutated payment behind.
   110  #[derive(Debug, Clone, PartialEq, Eq)]
   111  pub struct Payment {
   112      amount: i64,
   113      currency: Currency,
