   163
   164      /// Holds the funds: `Pending` -> `Authorized`.
   165      ///
   166      /// This is a bare transition without idempotency handling; use
   167      /// [`PaymentProcessor::authorize`] to deduplicate client retries by key.
   168      fn authorize(mut self, idempotency_key: &str) -> Result<Self, PaymentError> {
   169          if self.status != PaymentStatus::Pending {
   170              return Err(PaymentError::InvalidTransition {
   171                  from: self.status,
   172                  action: "authorize",
   173              });
   174          }
   175          self.status = PaymentStatus::Authorized;
   176          self.events.push(PaymentEvent::Authorized {
   177              idempotency_key: idempotency_key.to_owned(),
   178          });
   179          Ok(self)
   180      }
   181
   182      /// Captures `amount` minor units of the authorized funds.
   183      ///
   184      /// Allowed from `Authorized` or `PartiallyCaptured`; the total captured
   185      /// amount may never exceed the authorized amount.
   186      pub fn capture(mut self, amount: i64) -> Result<Self, PaymentError> {
   187          if amount <= 0 {
   188              return Err(PaymentError::NonPositiveAmount);
   189          }
   190          match self.status {
   191              PaymentStatus::Authorized | PaymentStatus::PartiallyCaptured => {}
   192              other => {
   193                  return Err(PaymentError::InvalidTransition {
   194                      from: other,
   195                      action: "capture",
   196                  })
   197              }
   198          }
   199          let available = self.amount - self.captured;
   200          if amount > available {
   201              return Err(PaymentError::CaptureExceedsAuthorized {
   202                  requested: amount,
   203                  authorized: self.amount,
   204              });
   205          }
   206          self.captured += amount;
   207          self.status = if self.captured == self.amount {
   208              PaymentStatus::Captured
   209          } else {
   210              PaymentStatus::PartiallyCaptured
   211          };
   212          self.events.push(PaymentEvent::Captured { amount });
   213          Ok(self)
   214      }
   215
   216      /// Refunds `amount` minor units of the captured funds.
   217      ///
   218      /// Allowed from `Captured` or `PartiallyRefunded` (i.e. only once the
   219      /// payment is fully captured); the total refunded amount may never exceed
   220      /// the captured amount.
   221      pub fn refund(mut self, amount: i64) -> Result<Self, PaymentError> {
   222          if amount <= 0 {
   223              return Err(PaymentError::NonPositiveAmount);
   224          }
   225          match self.status {
   226              PaymentStatus::Captured | PaymentStatus::PartiallyRefunded => {}
   227              other => {
   228                  return Err(PaymentError::InvalidTransition {
   229                      from: other,
   230                      action: "refund",
   231                  })
   232              }
   233          }
   234          let available = self.captured - self.refunded;
   235          if amount > available {
   236              return Err(PaymentError::RefundExceedsCaptured {
   237                  requested: amount,
   238                  captured: self.captured,
   239              });
   240          }
   241          self.refunded += amount;
   242          self.status = if self.refunded == self.captured {
   243              PaymentStatus::Refunded
   244          } else {
   245              PaymentStatus::PartiallyRefunded
   246          };
   247          self.events.push(PaymentEvent::Refunded { amount });
   248          Ok(self)
   249      }
   250
   251      /// Releases the held funds: `Authorized` -> `Voided`.
   252      pub fn void(mut self) -> Result<Self, PaymentError> {
   253          if self.status != PaymentStatus::Authorized {
   254              return Err(PaymentError::InvalidTransition {
   255                  from: self.status,
   256                  action: "void",
   257              });
   258          }
   259          self.status = PaymentStatus::Voided;
   260          self.events.push(PaymentEvent::Voided);
   261          Ok(self)
   262      }
   263  }
