   265  /// The outcome of a previously handled idempotency key.
   266  #[derive(Debug, Clone)]
   267  enum StoredAuthorization {
   268      Success(Payment),
   269      Failure(PaymentError),
   270  }
   271
   272  /// Drives payments through their lifecycle, providing idempotent authorization.
   273  #[derive(Debug, Default)]
   274  pub struct PaymentProcessor {
   275      inbox: HashMap<String, StoredAuthorization>,
   276  }
   277
   278  impl PaymentProcessor {
   279      /// Creates an empty processor with an empty idempotency inbox.
   280      pub fn new() -> Self {
   281          Self::default()
   282      }
   283
   284      /// Authorizes `payment`, deduplicating retries by `idempotency_key`.
   285      ///
   286      /// The first call with a given key performs the authorization (recording
   287      /// the result). Any later call with the same key returns that first result
   288      /// verbatim — success returns a clone of the originally authorized payment,
   289      /// failure returns the original error — without touching the payment or the
   290      /// state machine again.
   291      pub fn authorize(
   292          &mut self,
   293          payment: Payment,
   294          idempotency_key: &str,
   295      ) -> Result<Payment, PaymentError> {
   296          if let Some(stored) = self.inbox.get(idempotency_key) {
   297              return match stored {
   298                  StoredAuthorization::Success(payment) => Ok(payment.clone()),
   299                  StoredAuthorization::Failure(error) => Err(error.clone()),
   300              };
   301          }
   302
   303          let outcome = payment.authorize(idempotency_key);
   304          let stored = match &outcome {
   305              Ok(payment) => StoredAuthorization::Success(payment.clone()),
   306              Err(error) => StoredAuthorization::Failure(error.clone()),
   307          };
   308          self.inbox.insert(idempotency_key.to_owned(), stored);
   309          outcome
   310      }
   311  }
