    78      ///
    79      /// Returns [`PaymentError::InvalidTransition`] unless the payment is in the
    80      /// `Created` status.
    81      pub fn authorize(&mut self) -> PaymentResult<&PaymentEvent> {
    82          if self.status != PaymentStatus::Created {
    83              return Err(PaymentError::invalid_transition("authorize", self.status));
    84          }
    85
    86          self.status = PaymentStatus::Authorized;
    87          let description = format!("payment '{}' authorized", self.id);
    88          Ok(self.record(PaymentEventType::Authorized, None, description))
    89      }
    90
    91      /// Captures `amount` from the authorized amount.
    92      ///
    93      /// A capture may cover the full authorized amount (transitioning to
    94      /// `Captured`) or a portion of it (transitioning to `PartiallyCaptured`).
    95      ///
    96      /// # Errors
    97      ///
    98      /// - [`PaymentError::InvalidTransition`] if the payment is not
    99      ///   `Authorized` or `PartiallyCaptured`.
   100      /// - [`PaymentError::ZeroAmount`] if `amount` is zero.
   101      /// - [`PaymentError::AmountExceedsAuthorized`] if `amount` exceeds the
   102      ///   amount still available to capture.
   103      pub fn capture(&mut self, amount: Amount) -> PaymentResult<&PaymentEvent> {
   104          let current = self.status;
   105          if !matches!(
   106              current,
   107              PaymentStatus::Authorized | PaymentStatus::PartiallyCaptured
   108          ) {
   109              return Err(PaymentError::invalid_transition("capture", current));
   110          }
   111          if amount == 0 {
   112              return Err(PaymentError::ZeroAmount);
   113          }
   114
   115          let remaining = self.amount - self.captured_amount;
   116          if amount > remaining {
   117              return Err(PaymentError::AmountExceedsAuthorized { amount, remaining });
   118          }
   119
   120          self.captured_amount += amount;
   121          self.status = if self.captured_amount == self.amount {
   122              PaymentStatus::Captured
   123          } else {
   124              PaymentStatus::PartiallyCaptured
   125          };
   126
   127          let description = format!("captured {amount} {}", self.currency);
   128          Ok(self.record(PaymentEventType::Captured, Some(amount), description))
   129      }
   130
   131      /// Refunds `amount` from the captured amount.
   132      ///
   133      /// A refund may cover the full captured amount (transitioning to
   134      /// `Refunded`) or a portion of it (transitioning to `PartiallyRefunded`).
   135      ///
   136      /// # Errors
   137      ///
   138      /// - [`PaymentError::InvalidTransition`] if the payment is not `Captured`,
   139      ///   `PartiallyCaptured` or `PartiallyRefunded`.
   140      /// - [`PaymentError::ZeroAmount`] if `amount` is zero.
   141      /// - [`PaymentError::AmountExceedsCaptured`] if `amount` exceeds the
   142      ///   captured amount still available to refund.
   143      pub fn refund(&mut self, amount: Amount) -> PaymentResult<&PaymentEvent> {
   144          let current = self.status;
   145          if !matches!(
   146              current,
   147              PaymentStatus::Captured
   148                  | PaymentStatus::PartiallyCaptured
   149                  | PaymentStatus::PartiallyRefunded
   150          ) {
   151              return Err(PaymentError::invalid_transition("refund", current));
   152          }
   153          if amount == 0 {
   154              return Err(PaymentError::ZeroAmount);
   155          }
   156
   157          let available = self.captured_amount - self.refunded_amount;
   158          if amount > available {
   159              return Err(PaymentError::AmountExceedsCaptured { amount, available });
   160          }
   161
   162          self.refunded_amount += amount;
   163          self.status = if self.refunded_amount == self.captured_amount {
   164              PaymentStatus::Refunded
   165          } else {
   166              PaymentStatus::PartiallyRefunded
   167          };
   168
   169          let description = format!("refunded {amount} {}", self.currency);
   170          Ok(self.record(PaymentEventType::Refunded, Some(amount), description))
   171      }
