   173      /// Voids an authorization, transitioning `Authorized` → `Voided`.
   174      ///
   175      /// # Errors
   176      ///
   177      /// Returns [`PaymentError::InvalidTransition`] unless the payment is in the
   178      /// `Authorized` status.
   179      pub fn void(&mut self) -> PaymentResult<&PaymentEvent> {
   180          if self.status != PaymentStatus::Authorized {
   181              return Err(PaymentError::invalid_transition("void", self.status));
   182          }
   183
   184          self.status = PaymentStatus::Voided;
   185          let description = format!("payment '{}' voided", self.id);
   186          Ok(self.record(PaymentEventType::Voided, None, description))
   187      }
