   194      /// Returns the original authorized amount.
   195      pub fn amount(&self) -> Amount {
   196          self.amount
   197      }
   198
   199      /// Returns the currency.
   200      pub fn currency(&self) -> Currency {
   201          self.currency
   202      }
   203
   204      /// Returns the current lifecycle status.
   205      pub fn status(&self) -> PaymentStatus {
   206          self.status
   207      }
   208
   209      /// Returns the total amount captured so far.
   210      pub fn captured_amount(&self) -> Amount {
   211          self.captured_amount
   212      }
   213
   214      /// Returns the total amount refunded so far.
   215      pub fn refunded_amount(&self) -> Amount {
   216          self.refunded_amount
   217      }
   218
   219      /// Returns the amount still available to capture.
   220      pub fn available_for_capture(&self) -> Amount {
   221          self.amount - self.captured_amount
   222      }
   223
   224      /// Returns the captured amount still available to refund.
   225      pub fn available_for_refund(&self) -> Amount {
   226          self.captured_amount - self.refunded_amount
   227      }
