   229      /// Returns the append-only event journal, in chronological order.
   230      pub fn events(&self) -> &[PaymentEvent] {
   231          &self.events
   232      }
   233
   234      /// Returns the most recent journal entry, if any.
   235      pub fn last_event(&self) -> Option<&PaymentEvent> {
   236          self.events.last()
   237      }
