   239      fn record(
   240          &mut self,
   241          event_type: PaymentEventType,
   242          amount: Option<Amount>,
   243          description: String,
   244      ) -> &PaymentEvent {
   245          let event = PaymentEvent::new(event_type, amount, self.status, description);
   246          self.events.push(event);
   247          self.events.last().expect("event was just pushed")
   248      }
